<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/config.php';
require_once __DIR__ . '/../../config/database.php';
require_once __DIR__ . '/../../config/functions.php';
require_once __DIR__ . '/../../config/session.php';
Session::start();
$userRole = Session::getUserRole();
if (!Session::isLoggedIn() || !in_array($userRole, ['hr_manager','hr_staff','admin'], true)) {
    header('Location: ' . APP_URL . 'index.php'); exit();
}
$selected_date = $_POST['selected_date'] ?? $_GET['date'] ?? date('Y-m-d');
$message = ''; $msg_type = 'success';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    $ids = isset($_POST['employee_ids']) && is_array($_POST['employee_ids']) ? array_values(array_unique(array_filter(array_map('intval', $_POST['employee_ids'])))) : [];
    if (!$ids && isset($_POST['employee_id'])) $ids = [(int)$_POST['employee_id']];
    try {
        if (!$ids && str_starts_with($action, 'bulk_')) {
            throw new RuntimeException('يرجى تحديد موظف واحد على الأقل.');
        }
        if ($action === 'bulk_check_in') {
            $mode = $_POST['bulk_work_mode'] ?? 'remote';
            foreach ($ids as $id) dbExecute("INSERT INTO attendance (employee_id,date,check_in,work_mode,status) VALUES (?, ?, ?, ?, 'present') ON DUPLICATE KEY UPDATE check_in=VALUES(check_in),work_mode=VALUES(work_mode),status='present'", [$id,$selected_date,date('H:i:s'),$mode]);
            $message = 'تم تسجيل الحضور للموظفين المحددين بنجاح.';
        } elseif ($action === 'bulk_check_out') {
            foreach ($ids as $id) dbExecute("UPDATE attendance SET check_out=? WHERE employee_id=? AND date=?", [date('H:i:s'),$id,$selected_date]);
            $message = 'تم تسجيل الانصراف للموظفين المحددين.';
        } elseif ($action === 'bulk_absent') {
            foreach ($ids as $id) dbExecute("INSERT INTO attendance (employee_id,date,status) VALUES (?,?,'absent') ON DUPLICATE KEY UPDATE status='absent'", [$id,$selected_date]);
            $message = 'تم تسجيل الغياب للموظفين المحددين.';
        } elseif ($action === 'bulk_leave') {
            foreach ($ids as $id) dbExecute("INSERT INTO attendance (employee_id,date,status) VALUES (?,?,'on_leave') ON DUPLICATE KEY UPDATE status='on_leave'", [$id,$selected_date]);
            $message = 'تم تسجيل الإجازة للموظفين المحددين.';
        } elseif ($action === 'check_in') {
            $id=(int)($_POST['employee_id']??0); $mode=$_POST['work_mode']??'remote';
            dbExecute("INSERT INTO attendance (employee_id,date,check_in,work_mode,status) VALUES (?, ?, ?, ?, 'present') ON DUPLICATE KEY UPDATE check_in=VALUES(check_in),work_mode=VALUES(work_mode),status='present'",[$id,$selected_date,date('H:i:s'),$mode]);
            $message=t('hr.attendance_recorded');
        } elseif ($action === 'check_out') {
            $id=(int)($_POST['employee_id']??0); dbExecute("UPDATE attendance SET check_out=? WHERE employee_id=? AND date=?",[date('H:i:s'),$id,$selected_date]); $message=t('hr.checkout_recorded');
        } elseif ($action === 'mark_absent') {
            $id=(int)($_POST['employee_id']??0); dbExecute("INSERT INTO attendance (employee_id,date,status) VALUES (?,?,'absent') ON DUPLICATE KEY UPDATE status='absent'",[$id,$selected_date]); $message=t('hr.absence_recorded');
        } elseif ($action === 'mark_leave') {
            $id=(int)($_POST['employee_id']??0); dbExecute("INSERT INTO attendance (employee_id,date,status) VALUES (?,?,'on_leave') ON DUPLICATE KEY UPDATE status='on_leave'",[$id,$selected_date]); $message=t('hr.attendance_leave_recorded');
        }
    } catch (Throwable $e) { $message = $e->getMessage(); $msg_type='error'; }
}
$employees=dbFetchAll("SELECT e.id,e.full_name,e.department_id,d.name_ar as dept_name FROM employees e LEFT JOIN departments d ON e.department_id=d.id WHERE e.status='active' ORDER BY e.full_name",[]);
$attendance_records=[]; foreach(dbFetchAll("SELECT * FROM attendance WHERE date=?",[$selected_date]) as $att) $attendance_records[(int)$att['employee_id']]=$att;
$stats=['present'=>0,'absent'=>0,'late'=>0,'on_leave'=>0]; foreach($attendance_records as $att){if(isset($stats[$att['status']]))$stats[$att['status']]++;}
$pageTitle=t('hr.attendance_title'); require_once __DIR__.'/../../includes/header.php';
?>
<style>
