ols select{height:35px;border:1px solid var(--line);border-radius:8px;padding:0 8px;font-size:.75rem;color:#475467;background:#fff;min-width:135px}.selection-bar{display:none;align-items:center;gap:7px;padding:8px 10px;background:#f1f6fc;border-bottom:1px solid #dbe7f5}.selection-bar.show{display:flex}.selection-count{font-size:.74rem;font-weight:800;color:var(--brand);margin-left:auto}.bulk-btn{height:30px;border:0;border-radius:7px;padding:0 9px;font-size:.7rem;font-weight:750;display:inline-flex;align-items:center;gap:5px;cursor:pointer}.bulk-in{background:#dff3e7;color:#176b40}.bulk-out{background:#fbe1e5;color:#a82e3b}.bulk-leave{background:#fff0bd;color:#785d00}.bulk-absent{background:#eceff3;color:#475467}.bulk-mode{height:30px;border:1px solid #d7e0eb;border-radius:7px;background:#fff;font-size:.7rem;padding:0 7px}.att3-table{width:100%;border-collapse:separate;border-spacing:0}.att3-table th{height:38px;background:#fafbfc;border-bottom:1px solid var(--line);font-size:.67rem;font-weight:800;color:#667085;text-align:right;padding:0 12px;white-space:nowrap}.att3-table td{height:54px;border-bottom:1px solid #f0f1f3;padding:7px 12px;font-size:.76rem;color:#344054;vertical-align:middle}.att3-table tbody tr:hover{background:#fbfcfe}.att3-table tbody tr:last-child td{border-bottom:0}.check-col{width:38px;text-align:center!important}.row-check,.head-check{width:15px;height:15px;accent-color:var(--brand);cursor:pointer}.person{min-width:185px}.person-name{font-size:.77rem;font-weight:800;color:#273444}.person-meta{font-size:.65rem;color:#98a2b3;margin-top:1px}.dept3{color:#667085;font-size:.72rem}.time3{font-variant-numeric:tabular-nums;font-weight:700;color:#344054}.time3.empty{font-weight:500;color:#adb5bd}.mode3{font-size:.67rem;font-weight:700;padding:3px 7px;background:#f1f3f5;border-radius:5px;color:#596579}.status3{display:inline-flex;align-items:center;gap:4px;border-radius:15px;padding:3px 8px;font-size:.67rem;font-weight:800}.status3.p{background:#eaf7ef;color:#167447}.status3.l{background:#fff5d7;color:#8a6700}.status3.a{background:#fdebed;color:#b42331}.status3.lv{background:#eaf5fb;color:#126c8e}.status3.e{background:#eef0f3;color:#667085}.row-action{display:flex;justify-content:flex-end;gap:5px;align-items:center}.row-action select{height:29px;border:1px solid var(--line);border-radius:6px;font-size:.68rem;padding:0 5px;max-width:95px}.row-btn{height:29px;border:0;border-radius:6px;padding:0 8px;font-size:.68rem;font-weight:750;cursor:pointer}.row-in{background:#eaf7ef;color:#167447}.row-out{background:#fdebed;color:#b42331}.row-leave{background:#fff4cf;color:#7b5c00}.done{font-size:.68rem;color:#98a2b3;display:inline-flex;align-items:center;gap:4px}.empty3{text-align:center!important;padding:35px!important;color:#98a2b3}@media(max-width:950px){.att3{padding:16px}.att3-kpis{grid-template-columns:repeat(2,1fr)}.att3-table{min-width:920px}.att3-panel{overflow-x:auto}}@media(max-width:600px){.att3-head{align-items:stretch;flex-direction:column}.att3-kpis{grid-template-columns:1fr 1fr}}
</style>
<div class="att3">
<div class="att3-head"><div><h1 class="att3-title"><i class="fas fa-calendar-check me-2" style="color:#1b4d8f"></i><?php echo e(t('hr.attendance_title')); ?></h1><div class="att3-sub">إدارة حضور وانصراف الموظفين بشكل يومي مع تنفيذ الإجراءات الفردية أو الجماعية.</div></div><div class="att3-date"><a href="?date=<?php echo htmlspecialchars(date('Y-m-d',strtotime($selected_date.' -1 day'))); ?>" title="اليوم السابق"><i class="fas fa-chevron-right"></i></a><form method="GET" class="m-0"><input type="date" name="date" value="<?php echo htmlspecialchars($selected_date); ?>" onchange="this.form.submit()"></form><a href="?date=<?php echo htmlspecialchars(date('Y-m-d',strtotime($selected_date.' +1 day'))); ?>" title="اليوم التالي"><i class="fas fa-chevron-left"></i></a></div></div>
<?php if($message): ?><div class="alert alert-<?php echo $msg_type==='error'?'danger':'success'; ?> py-2 px-3 mb-3" style="border-radius:8px;font-size:.78rem"><?php echo e($message); ?><button type="button" class="btn-close"></button></div><?php endif; ?>
<div class="att3-kpis"><div class="kpi p"><div><div class="kpi-label"><?php echo e(t('hr.present')); ?></div><div class="kpi-num"><?php echo $stats['present']; ?></div></div><div class="kpi-mark"><i class="fas fa-check"></i></div></div><div class="kpi l"><div><div class="kpi-label"><?php echo e(t('hr.late')); ?></div><div class="kpi-num"><?php echo $stats['late']; ?></div></div><div class="kpi-mark"><i class="fas fa-clock"></i></div></div><div class="kpi a"><div><div class="kpi-label"><?php echo e(t('hr.absent')); ?></div><div class="kpi-num"><?php echo $stats['absent']; ?></div></div><div class="kpi-mark"><i class="fas fa-user-xmark"></i></div></div><div class="kpi lv"><div><div class="kpi-label"><?php echo e(t('hr.on_leave')); ?></div><div class="kpi-num"><?php echo $stats['on_leave']; ?></div></div><div class="kpi-mark"><i class="fas fa-calendar-day"></i></div></div></div>
<div class="att3-panel">
<div class="att3-tools"><div class="att3-search"><i class="fas fa-search"></i><input id="attSearch" type="search" placeholder="البحث باسم الموظف..." autocomplete="off"></div><select id="attDept"><option value="">كل الأقسام</option><?php $deps=[];foreach($employees as $e){if(!empty($e['dept_name']))$deps[$e['department_id']]=$e['dept_name'];}foreach($deps as $d): ?><option value="<?php echo htmlspecialchars($d); ?>"><?php echo htmlspecialchars($d); ?></option><?php endforeach; ?></select><select id="attStatus"><option value="">كل الحالات</option><option value="present"><?php echo e(t('hr.present')); ?></option><option value="late"><?php echo e(t('hr.late')); ?></option><option value="absent"><?php echo e(t('hr.absent')); ?></option><option value="on_leave"><?php echo e(t('hr.on_leave')); ?></option></select></div>
<form method="POST" id="bulkForm"><input type="hidden" name="selected_date" value="<?php echo htmlspecialchars($selected_date); ?>"><div class="selection-bar" id="selectionBar"><select name="bulk_work_mode" class="bulk-mode"><option value="remote"><?php echo e(t('hr.work_mode_remote')); ?></option><option value="onsite"><?php echo e(t('hr.work_mode_onsite')); ?></option><option value="hybrid"><?php echo e(t('hr.work_mode_hybrid')); ?></option></select><button type="submit" name="action" value="bulk_check_in" class="bulk-btn bulk-in"><i class="fas fa-right-to-bracket"></i> تسجيل حضور</button><button type="submit" name="action" value="bulk_check_out" class="bulk-btn bulk-out"><i class="fas fa-right-from-bracket"></i> تسجيل انصراف</button><button type="submit" name="action" value="bulk_leave" class="bulk-btn bulk-leave"><i class="fas fa-calendar-day"></i> إجازة</button><button type="submit" name="action" value="bulk_absent" class="bulk-btn bulk-absent"><i class="fas fa-user-xmark"></i> غياب</button><span class="selection-count" id="selectionCount">0 محدد</span></div>
</form>
<table class="att3-table"><thead><tr><th class="check-col"><input class="head-check" id="selectAll" type="checkbox" form="bulkForm" title="تحديد الكل"></th><th>الموظف</th><th>القسم</th><th>الحضور</th><th>الانصراف</th><th>نمط العمل</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>
<?php if(!$employees): ?><tr><td colspan="8" class="empty3">لا يوجد موظفون نشطون.</td></tr><?php endif; ?>
<?php foreach($employees as $emp): $att=$attendance_records[(int)$emp['id']]??null; $status=$att['status']??''; $statusLabel=$status==='present'?t('hr.present'):($status==='late'?t('hr.late'):($status==='absent'?t('hr.absent'):($status==='on_leave'?t('hr.on_leave'):'غير مسجل'))); $statusClass=$status==='present'?'p':($status==='late'?'l':($status==='absent'?'a':($status==='on_leave'?'lv':'e'))); ?>
<tr data-name="<?php echo htmlspecialchars(mb_strtolower($emp['full_name']??'')); ?>" data-dept="<?php echo htmlspecialchars($emp['dept_name']??''); ?>" data-status="<?php echo htmlspecialchars($status); ?>"><td class="check-col"><input class="row-check" type="checkbox" name="employee_ids[]" value="<?php echo (int)$emp['id']; ?>" form="bulkForm"></td><td><div class="person"><div><div class="person-name"><?php echo e($emp['full_name']); ?></div><div class="person-meta">#<?php echo (int)$emp['id']; ?></div></div></div></td><td class="dept3"><?php echo e($emp['dept_name']??'—'); ?></td><td><span class="time3 <?php echo empty($att['check_in'])?'empty':''; ?>"><?php echo !empty($att['check_in'])?e(date('h:i A',strtotime($att['check_in']))):'—'; ?></span></td><td><span class="time3 <?php echo empty($att['check_out'])?'empty':''; ?>"><?php echo !empty($att['check_out'])?e(date('h:i A',strtotime($att['check_out']))):'—'; ?></span></td><td><?php echo !empty($att['work_mode'])?'<span class="mode3">'.e(t('hr.work_mode_'.$att['work_mode'])).'</span>':'<span class="time3 empty">—</span>'; ?></td><td><span class="status3 <?php echo $statusClass; ?>"><i class="fas <?php echo $statusClass==='p'?'fa-check':($statusClass==='l'?'fa-clock':($statusClass==='a'?'fa-user-xmark':($statusClass==='lv'?'fa-calendar-day':'fa-minus'))); ?>"></i><?php echo e($statusLabel); ?></span></td><td><div class="row-action"><?php if(!$att || empty($att['check_in'])): ?><form method="POST" class="m-0"><input type="hidden" name="selected_date" value="<?php echo htmlspecialchars($selected_date); ?>"><input type="hidden" name="employee_id" value="<?php echo (int)$emp['id']; ?>"><input type="hidden" name="action" value="check_in"><select name="work_mode"><option value="remote"><?php echo e(t('hr.work_mode_remote')); ?></option><option value="onsite"><?php echo e(t('hr.work_mode_onsite')); ?></option><option value="hybrid"><?php echo e(t('hr.work_mode_hybrid')); ?></option></select><button class="row-btn row-in" type="submit"><i class="fas fa-right-to-bracket"></i></button></form><?php elseif(empty($att['check_out']) && $status==='present'): ?><form method="POST" class="m-0"><input type="hidden" name="selected_date" value="<?php echo htmlspecialchars($selected_date); ?>"><input type="hidden" name="employee_id" value="<?php echo (int)$emp['id']; ?>"><input type="hidden" name="action" value="check_out"><button class="row-btn row-out" type="submit"><i class="fas fa-right-from-bracket"></i></button></form><?php else: ?><span class="done"><i class="fas fa-check"></i> مكتمل</span><?php endif; ?><?php if(!$att || empty($att['check_in']) || $status==='absent'): ?><form method="POST" class="m-0"><input type="hidden" name="selected_date" value="<?php echo htmlspecialchars($selected_date); ?>"><input type="hidden" name="employee_id" value="<?php echo (int)$emp['id']; ?>"><input type="hidden" name="action" value="mark_leave"><button class="row-btn row-leave" type="submit" title="إجازة"><i class="fas fa-calendar-day"></i></button></form><?php endif; ?></div></td></tr>
<?php endforeach; ?></tbody></table></div></div>
<script>
(function(){
 const search=document.getElementById('attSearch'),dept=document.getElementById('attDept'),status=document.getElementById('attStatus'),selectAll=document.getElementById('selectAll'),bar=document.getElementById('selectionBar'),count=document.getElementById('selectionCount'),form=document.getElementById('bulkForm');
 const rows=()=>Array.from(document.querySelectorAll('.att3-table tbody tr[data-name]'));
 function apply(){const q=(search.value||'').trim().toLowerCase(),d=dept.value,s=status.value;rows().forEach(r=>{const ok=(!q||r.dataset.name.includes(q))&&(!d||r.dataset.dept===d)&&(!s||r.dataset.status===s);r.style.display=ok?'':'none';});syncAll();}
 function checks(){return Array.from(document.querySelectorAll('.row-check'));}
 function syncAll(){const visible=checks().filter(c=>c.closest('tr').style.display!=='none'),selected=checks().filter(c=>c.checked);count.textContent=selected.length+' محدد';bar.classList.toggle('show',selected.length>0);selectAll.checked=visible.length>0&&visible.every(c=>c.checked);selectAll.indeterminate=visible.some(c=>c.checked)&&!selectAll.checked;}
 search.addEventListener('input',apply);dept.addEventListener('change',apply);status.addEventListener('change',apply);
 selectAll.addEventListener('change',function(){checks().forEach(c=>{if(c.closest('tr').style.display!=='none')c.checked=this.checked;});syncAll();});
 checks().forEach(c=>c.addEventListener('change',syncAll));
 form.addEventListener('submit',function(e){if(!checks().some(c=>c.checked)){e.preventDefault();alert('يرجى تحديد موظف واحد على الأقل.');}});
 syncAll();
})();
</script>
